document.outline_text:
[
  {
    "intent": "Hook and introduce the reliability problem of long-running validation when local agent sessions disconnect.",
    "summary": "I open with the builder's reality of agent timeouts, explaining why scenario suites need lifecycle durability. I introduce our scenario test runner, test-genie, which takes over execution after the command returns so run state, logs, and evidence remain intact even if caller sessions terminate.",
    "target_words": 260
  },
  {
    "intent": "Detail the operator workflow for initiating and monitoring background validation suites.",
    "summary": "I walk through the concrete three-step shipped workflow: operators trigger the suite, record the run identifier, and issue a single wait command against the server-owned run to collect finished state without keeping an active terminal attached.",
    "target_words": 280
  },
  {
    "intent": "Analyze the critical failure path distinction between client disconnections and actual test failures.",
    "summary": "I explain why a cancelled client is not the same thing as an aborted run, showing how separating client disconnection from test execution preserves authentic failure evidence and prevents network interruptions from masking product defects.",
    "target_words": 300
  },
  {
    "intent": "Synthesize how durable, addressable test runs establish a governed control plane for team handoffs.",
    "summary": "I conclude by explaining how server-owned validation turns waiting into a governed capability, allowing subsequent operators to inspect preserved evidence and complete handoffs directly from the original test record.",
    "target_words": 260
  }
]

